INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21601, 'Nahum 3:4', 'Nahum', 3, 4, '&nbsp;ځکه چې نينوه د يوې بې‌حيا زناکارې په شان ده، چې ناز نخرې کوى، او خپل ښائست لکه د جادو استعمالوى، چا چې په کنجرتوب سره قومونه خپل غلامان کړى دى او په خپل جادو سره يې خلق راګېر کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21602, 'Nahum 3:5', 'Nahum', 3, 5, '&nbsp;زۀ ستا خلاف يم، مالِک خُدائ ربُ الافواج فرمائى. زۀ به ستا لمن ستا په مخ دراوچته کړم. زۀ به قومونو ته تا لغړه کړم او مُلکونو ته به دې وشرموم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21603, 'Nahum 3:6', 'Nahum', 3, 6, '&nbsp;زۀ به په تا ګند دروغورزوم، زۀ به تا سپکه کړم او تا نه به يو تماشه جوړه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21604, 'Nahum 3:7', 'Nahum', 3, 7, '&nbsp;هغه ټول څوک چې تا ګورى هغوئ به تا نه وتښتى او وائى به، د نينوه نه کنډر جوړ شوے دے، څوک به د هغې دپاره ماتم کوى؟ څوک به هم نۀ وى چې تا له تسلى درکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21605, 'Nahum 3:8', 'Nahum', 3, 8, '&nbsp;آيا تۀ د تيبس نه ښۀ يې، چې د نيل په درياب باندې آباد دے، چې ګېرچاپېره ترې نه اوبۀ دى؟ درياب د هغې دفاع وه او اوبۀ د هغې دېوالونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21606, 'Nahum 3:9', 'Nahum', 3, 9, '&nbsp;ايتهوپيا او مِصر د دې لامحدوده زور وو، فوط او ليبيا د دې اِتحاديان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21607, 'Nahum 3:10', 'Nahum', 3, 10, '&nbsp;خو اوس هغه ونيولے شوه او جلاوطنه کړے شوه. د هغې بچى د هرې کوڅې په سر کښې ټوکړې ټوکړې شُو. د غلامۍ دپاره د هغې په مشرانو پچه واچولے شوه، او د هغې ټول مشران په زنځيرونو وتړلے شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21608, 'Nahum 3:11', 'Nahum', 3, 11, '&nbsp;تۀ به هم لکه د نشيانو نشه شې، تۀ به خپل ځان پټوې او د دشمن نه به پناه غواړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21609, 'Nahum 3:12', 'Nahum', 3, 12, '&nbsp;ستا ټولې قلعه ګانې لکه د اينځر د هغه ونو په شان دى چې وړومبۍ مېوه يې پخه وى، کله چې دا وخوځولے شى، نو اينځر يې د خوړونکى خولۀ کښې راوغورزيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21610, 'Nahum 3:13', 'Nahum', 3, 13, '&nbsp;خپلو فوجيانو ته وګوره، هغوئ ټول لکه د ښځو په شان کمزورى دى. ستا د مُلک دروازې، ستا دشمنانو ته خلاصې دى. اور د دې اړمونه سوزولى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21611, 'Nahum 3:14', 'Nahum', 3, 14, '&nbsp;د محاصرې دپاره اوبۀ ډکې کړه، او خپلې مورچې مضبوطې کړه. خټه جوړه کړه، په پښو يې نرمه کړه، د خښتو د جوړولو دپاره يې تياره کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21612, 'Nahum 3:15', 'Nahum', 3, 15, '&nbsp;خو اور به تا وسوزوى، تُوره به دې په مينځ دوه کړى. دشمن به دې لکه د قحطۍ د مُولخانو په شان وخورى. تر دې کۀ تاسو د قحطۍ مُولخانو په شان ډېر هم شئ خو د تښتېدلو لار به مو نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21613, 'Nahum 3:16', 'Nahum', 3, 16, '&nbsp;تا د خپلو سوداګرو شمېر زيات کړے دے تر دې چې د هغوئ شمېر د آسمان د ستورو نه هم زيات دے، خو لکه د مُولخانو هغوئ زمکه صفا کړى او بيا والوځى او لاړ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21614, 'Nahum 3:17', 'Nahum', 3, 17, '&nbsp;ستا محافظان د قحطۍ د مُولخانو په شان دى، او ستا آفسران د قحطۍ د مُولخانو د لښکر په شان دى چې په ژمى کښې په دېوالونو کښېنى. خو کله چې نمر راښکاره شى نو دوئ والوځى او لاړ شى، او چا ته نۀ معلوميږى چې چرته ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21615, 'Nahum 3:18', 'Nahum', 3, 18, '&nbsp;اے د اسوريى بادشاه، ستا د قوم شپونکى اودۀ دى، ستا مشران د آرام دپاره پراتۀ دى. ستا خلق په غرونو خوارۀ وارۀ شوى دى او څوک نشته چې دوئ رايوځائ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21616, 'Nahum 3:19', 'Nahum', 3, 19, '&nbsp;ستا زخم هيڅ يو څيز هم نۀ روغوى، ستا زخم وژونکے دے. هر څوک چې ستا په حقله ستا په راغورزېدو خبر شى هغه لاسونه پړقوى، ځکه داسې څوک نشته چې ستا د نۀ ختمېدونکى ظلم نه خلاص شوى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21617, 'Habakkuk 1:1', 'Habakkuk', 1, 1, '&nbsp;هغه پېغام چې حبقُوق پېغمبر ته په رويا کښې مِلاو شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21618, 'Habakkuk 1:2', 'Habakkuk', 1, 2, '&nbsp;ترڅو به، اے مالِکه خُدايه، زۀ د مدد دپاره چغې وهم، خو تۀ جواب نۀ راکوې؟ زۀ درته د ظلم په حقله چغې وهم، خو تۀ مينځ ته نۀ راځې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21619, 'Habakkuk 1:3', 'Habakkuk', 1, 3, '&nbsp;تۀ ولې ما دې ته جوړوې چې بې‌اِنصافى وګورم؟ تۀ ولې بد برداشت کوې؟ تباهى او ظلم، بحث مباحثى او اختلافات زما د وړاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21620, 'Habakkuk 1:4', 'Habakkuk', 1, 4, '&nbsp;ځکه خو شريعت بې‌اثره دے او اِنصاف هيڅکله نۀ کيږى. بدعمله خلق د صادقانو نه راتاو شى چې اِنصاف تالا والا کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21621, 'Habakkuk 1:5', 'Habakkuk', 1, 5, '&nbsp;”قومونو ته وګورئ او نظر پرې ساتئ، او حېران شئ. ځکه چې زۀ به ستاسو د ژوند په دوران کښې يو داسې کار وکړم چې تاسو به پرې يقين نۀ کوئ کۀ تاسو ته وئيلے شوى هم وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21622, 'Habakkuk 1:6', 'Habakkuk', 1, 6, '&nbsp;زۀ بابليان راوچتوم، چې ظالمان او بې‌رحمه خلق دى. هغوئ په ټوله دُنيا کښې په مخه روان دى چې هغه ځايونه قبضه کړى چې د دوئ نۀ دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21623, 'Habakkuk 1:7', 'Habakkuk', 1, 7, '&nbsp;هغوئ يره او دهشت خورونکى خلق دى، د هغوئ قانون د خپل ځانونو دپاره دے او خپل عزت په خپله زياتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21624, 'Habakkuk 1:8', 'Habakkuk', 1, 8, '&nbsp;د هغوئ آسونه د پړانګانو نه تېز دى، په شپه کښې د ليوۀ نه خطرناک دى. د هغوئ په آسونو سوارۀ فوجيان په تېزۍ سره راروان دى، د هغوئ د آسونو سوارۀ د لرې لرې نه راځى. هغوئ لکه د باز په شان غوټه وهلو له تېز الوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21625, 'Habakkuk 1:9', 'Habakkuk', 1, 9, '&nbsp;هغوئ ټول په ظلم زياتى سره راځى. د هغوئ لښکرې لکه د صحرا د طوفان په شان مخکښې ځى او لکه د شګو په شان قېديان غونډوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21626, 'Habakkuk 1:10', 'Habakkuk', 1, 10, '&nbsp;هغوئ بادشاهان سپکوى او حکمرانانو له پېغور ورکوى. هغوئ په ټولو قلعه بند ښارونو پورې خندا کوى، هغوئ به د ښار نه ګېرچاپېره د خاورو ډيرى جوړ کړى او قبضه به يې کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21627, 'Habakkuk 1:11', 'Habakkuk', 1, 11, '&nbsp;بيا به هغوئ لکه د طوفان په شان د ځان سره هر څۀ جارُو کړى او تېر شى. دا ګناهګاران دى، د چا چې خپل طاقت د هغوئ معبود دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21628, 'Habakkuk 1:12', 'Habakkuk', 1, 12, '&nbsp;اے مالِکه خُدايه، آيا تۀ د ازل نه موجود نۀ يې؟ زما پاکه خُدايه، زما مقدس ذاته، مونږ به نۀ مرو. اے مالِکه خُدايه، تا هغوئ منتخب کړل چې حساب وکړى، اے ګټه، تا هغوئ مقرر کړل چې سزا ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21629, 'Habakkuk 1:13', 'Habakkuk', 1, 13, '&nbsp;خو ستا سترګې بد کتلو کښې ډيرې پاکې دى، تۀ بد نۀ شې برداشت کولے. بيا ولې تۀ دوکه باز برداشت کوې؟ بيا ولې تۀ خاموش يې کله چې بدعمله هغوئ لواړ تېروى څوک چې د هغوئ نه زيات صادق دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21630, 'Habakkuk 1:14', 'Habakkuk', 1, 14, '&nbsp;تۀ انسانان د سمندر د کبانو په شان جوړوې، لکه څنګه چې د هغوئ سمندرى قبيلې حکمران نۀ لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21631, 'Habakkuk 1:15', 'Habakkuk', 1, 15, '&nbsp;بدعمله دشمن هغوئ ټول په کُنډو سره راوباسى، هغوئ په خپل جال کښې رانيسى، هغوئ په خپل راښکوونکى جال کښې راجمع کوى، او بيا هغه خوشحالى کوى او خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21632, 'Habakkuk 1:16', 'Habakkuk', 1, 16, '&nbsp;په دې وجه هغه د خپل ښکار د جالونو عبادت کوى او په مخکښې ورته خوشبويۍ سوزوى، د خپل جال په وجه هغه ښۀ ژوند تېروى او د خوښې خوراکونه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21633, 'Habakkuk 1:17', 'Habakkuk', 1, 17, '&nbsp;آيا هغه مسلسل خپل جال خالى کوى او قومونه په بې‌رحمۍ سره تباه کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21634, 'Habakkuk 2:1', 'Habakkuk', 2, 1, '&nbsp;زۀ به څوکيدارۍ ته ودرېږم او په خپله به په برج باندې وخېژم، زۀ به ګورم چې هغه به ما ته څۀ وائى، او چې زۀ به د خپل شکايت څۀ جواب ورکوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21635, 'Habakkuk 2:2', 'Habakkuk', 2, 2, '&nbsp;بيا مالِک خُدائ د حبقُوق دُعا ته جواب ورکړو، ”زۀ چې څۀ تا ته په رويا کښې څرګندوم هغه په تختو باندې داسې وليکه چې هر څوک يې په آسانۍ سره لوستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21636, 'Habakkuk 2:3', 'Habakkuk', 2, 3, '&nbsp;نو ځکه رويا د مقرر وخت انتظار کوى، دا د آخرت په حقله خبرې کوى او دا به دروغ ثابت نۀ شى. اګر کۀ دا وخت اخلى، د دې انتظار وکړه، دا به خامخا پوره شى او ايسار به نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21637, 'Habakkuk 2:4', 'Habakkuk', 2, 4, '&nbsp;مغروره ته وګوره، هغوئ په خپل ځان يقين ساتى، او د هغوئ ژوند کوږ دے. څوک چې صادق وى هغه به په ايمان پائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21638, 'Habakkuk 2:5', 'Habakkuk', 2, 5, '&nbsp;په حقيقت کښې مال حال هغوئ دوکه کوى، هغوئ مغروره دى او هيڅکله هم په آرام نۀ وى. ځکه چې هغوئ دومره حرصناک دى څومره چې قبر وى او لکه د مرګ په شان هيڅکله هم نۀ مړيږى، هغوئ خپل ځان ته ټول قومونه راغونډوى او ټول خلق قبضه کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21639, 'Habakkuk 2:6', 'Habakkuk', 2, 6, '&nbsp;آيا هغوئ ټول به هغۀ ته په خندا او سپکه توګه پېغور ورنۀ کړى، او وائى به چې، ”په هغۀ دې افسوس وى څوک چې د غلا څيزونه جمع کوى او خپل ځان په قلنګ اخستلو سره مالداره کوى.“ دا به ترڅو پورې جارى وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21640, 'Habakkuk 2:7', 'Habakkuk', 2, 7, '&nbsp;آيا ستا قرضدار به ناڅاپه راوچت نۀ شى؟ آيا هغوئ به بېدار نۀ شى او تا به ونۀ لړزوى؟ نو بيا به تۀ د هغوئ ښکار شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21641, 'Habakkuk 2:8', 'Habakkuk', 2, 8, '&nbsp;ځکه چې تاسو ډېر قومونه لوټ کړى دى، کوم خلق چې ژوندى پاتې شى هغوئ به تاسو لوټ کړى. ځکه چې تاسو د انسانانو وينه تويه کړې ده، او تاسو مُلکونه او ښارونه او په دې کښې ټول خلق تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21642, 'Habakkuk 2:9', 'Habakkuk', 2, 9, '&nbsp;”افسوس په هغه چا چې خپله بادشاهى په ناجائزه ګټه جوړوى او خپله جاله په اوچت ځائ کښې جوړوى، د دې دپاره چې د تباهۍ د ګرفت نه بچ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21643, 'Habakkuk 2:10', 'Habakkuk', 2, 10, '&nbsp;تاسو د ډېرو خلقو د تباهۍ منصوبه جوړه کړه، په دې طريقه تاسو خپل قوم وشرمولو او خپل ژوند مو په کښې تباه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21644, 'Habakkuk 2:11', 'Habakkuk', 2, 11, '&nbsp;د دېوالونو کاڼى به هم تا پسې چغې کړى، او په چت کښې د لرګى تيرونه به هم فرياد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21645, 'Habakkuk 2:12', 'Habakkuk', 2, 12, '&nbsp;افسوس په هغه چا څوک چې په وينه توېدو ښار آبادوى او په جرم باندې ښار قائموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21646, 'Habakkuk 2:13', 'Habakkuk', 2, 13, '&nbsp;آيا مالِک خُدائ ربُ الافواج دا نۀ ده مقرره کړې چې د خلقو محنت صرف د اور دپاره خشاک دے، او قومونه خپل ځانونه هسې ستړى کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21647, 'Habakkuk 2:14', 'Habakkuk', 2, 14, '&nbsp;ځکه چې زمکه به د مالِک خُدائ د جلال د عِلم نه داسې ډکه شى لکه څنګه چې سمندر د اوبو نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21648, 'Habakkuk 2:15', 'Habakkuk', 2, 15, '&nbsp;افسوس په هغه چا چې خپل ګاونډى له شراب ورکوى، د شرابو د مشک نه ورته تر هغې پورې اچوى چې دوئ نشه شى، نو چې هغه د هغوئ لغړ بدنونه وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21649, 'Habakkuk 2:16', 'Habakkuk', 2, 16, '&nbsp;خو تۀ به زر د جلال په ځائ د شرم سره مخ شې. اوس ستا وار دے، وڅښه او ناسنته ځان لغړ کړه. د مالِک خُدائ د ښى لاس نه جام تا ته راروان دے، او سپکاوے به ستا جلال ختم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21650, 'Habakkuk 2:17', 'Habakkuk', 2, 17, '&nbsp;کوم ظلم چې تا لبنان سره وکړو هغه به تا له شکست درکړى، او کوم ظلم چې تا په ځناورو وکړو هغوئ به تا نه بدل واخلى. تا د انسان وينه تويه کړې ده، تا د زمکې په مخ کلى او ښارونه او په دې کښې ټول مخلوق تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21651, 'Habakkuk 2:18', 'Habakkuk', 2, 18, '&nbsp;د هغه بُت څۀ فائده ده، چې انسان تراشلے وى؟ يا هغه مجسمه چې د دروغو تعليم ورکوى؟ ځکه چې څوک دا جوړوى هغه په خپل جوړ کړى څيز اعتماد کوى، هغه جوړ کړى بُتان چې خبرې نۀ شى کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21652, 'Habakkuk 2:19', 'Habakkuk', 2, 19, '&nbsp;افسوس په هغوئ څوک چې لرګى ته وائى، ژوندے شه. يا بې‌ساه کاڼى ته وائى، پاڅه. آيا دا دوئ ته هدايت ورکولے شى؟ دا په سرو او سپينو زرو پټ وى، خو په کښې ساه نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21653, 'Habakkuk 2:20', 'Habakkuk', 2, 20, '&nbsp;خو مالِک خُدائ په خپل مقدس کور کښې دے، پرېږده چې ټوله زمکه د هغۀ په حضور کښې خاموشه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21654, 'Habakkuk 3:1', 'Habakkuk', 3, 1, '&nbsp;د حبقُوق پېغمبر دُعا.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21655, 'Habakkuk 3:2', 'Habakkuk', 3, 2, '&nbsp;اے مالِکه خُدايه، زۀ ستا د شُهرت نه خبر يم، ستا د عجيبه کارونو په وجه زۀ په يره کښې يم، اے مالِکه خُدايه. زمونږ د ژوند په ورځو کښې خپل کار تازه کړه، زمونږ په وخت کښې هغه دوباره څرګند کړه. او په خپله غصه کښې دې رحم ياد ساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21656, 'Habakkuk 3:3', 'Habakkuk', 3, 3, '&nbsp;خُدائ پاک د تيمان نه راروان دے، د فاران د غرونو نه هغه مقدس ذات راروان دے. ‎د هغۀ د شان او شوکت نه آسمانونه ډک شوى دى او د هغۀ ثناء صِفت زمکه ډکه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21657, 'Habakkuk 3:4', 'Habakkuk', 3, 4, '&nbsp;د هغۀ شان او شوکت لکه د راختونکى نمر په شان وو، او د هغۀ د لاس نه رڼاګانې ځلېدلې، په کوم کښې چې د هغۀ قدرت پټ انغښتے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21658, 'Habakkuk 3:5', 'Habakkuk', 3, 5, '&nbsp;وبا د هغۀ نه مخکښې لاړه، او طاعون د هغۀ قدمونو پسې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21659, 'Habakkuk 3:6', 'Habakkuk', 3, 6, '&nbsp;هغه چې ودرېدو، او زمکه يې خوځوله، هغۀ کتل او قومونه يې لړزول. پخوانى غرونه ذرې ذرې کېدل، او د ډيرې زمانې غونډۍ راغورزېدلې. د شروع نه د هغۀ تلل داسې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21660, 'Habakkuk 3:7', 'Habakkuk', 3, 7, '&nbsp;ما د کوشن د خلقو خېمې په مصيبت کښې وليدلې، د ميديانيانو د اوسېدو ځائ په تکليف کښې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21661, 'Habakkuk 3:8', 'Habakkuk', 3, 8, '&nbsp;آيا تۀ سيندونو ته غصه وې، اے مالِکه خُدايه؟ ولې ستا قهر د نِهرونو خلاف وو؟ ولې تۀ د سمندر خلاف غصه وې کله چې تۀ په خپلو آسونو او د فتحې په جنګى ګاډو سور وې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21662, 'Habakkuk 3:9', 'Habakkuk', 3, 9, '&nbsp;تا خپله لينده راښکاره کړه، تا د ډېرو غشو دپاره آواز وکړو. تا دريابونو سره زمکه په مينځ دوه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21663, 'Habakkuk 3:10', 'Habakkuk', 3, 10, '&nbsp;غرونو تۀ وليدلې او ولړزېدل، د اوبو سېلابونه وبهېدل، ژورو اوبو شور جوړ کړو، او خپلې چپې يې اوچتې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21664, 'Habakkuk 3:11', 'Habakkuk', 3, 11, '&nbsp;او څنګه چې ستا د نېزې ځلا وپړقېدله او ستا د ويشتلے شوو غشو رڼا ته، په آسمان کښې نمر او سپوږمۍ په خپل ځائ ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21665, 'Habakkuk 3:12', 'Habakkuk', 3, 12, '&nbsp;په غصه کښې تۀ په زمکه وګرځېدلې، او په قهر کښې تا قومونه چخڼى کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21666, 'Habakkuk 3:13', 'Habakkuk', 3, 13, '&nbsp;تۀ د خپلو خلقو بچ کولو دپاره بهر راغلې، چې خپل غوره کړے شوى بچ کړې. تا د بدعمله وطن مشر چخڼى کړل، تا هغوئ د سر نه تر پښو پورې بربنډ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21667, 'Habakkuk 3:14', 'Habakkuk', 3, 14, '&nbsp;هغوئ د خوشحالۍ نه داسې چغې وهلې لکه چې غريبانان يې د څۀ مخالفت نه بغېر لوټ کړل. تا په خپلو نېزو د هغوئ سرونه مات کړل کله چې د هغۀ جنګيالو زمونږ د تس نس کولو دپاره په مونږ حمله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21668, 'Habakkuk 3:15', 'Habakkuk', 3, 15, '&nbsp;تا سمندر د خپلو آسونو د پښو لاندې کړو، زورَورې اوبۀ دې په تاوېدو کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21669, 'Habakkuk 3:16', 'Habakkuk', 3, 16, '&nbsp;ما واورېدل او زړۀ مې په رپېدو شو، زما شونډې په هغه آواز سره په رپېدو شوې، زما هډُوکى وراستۀ شول، او زما پښې په لړزېدو شوې. تر اوسه زۀ د مصيبت د هغه ورځې په صبر سره انتظار کوم چې په هغه قوم به راشى څوک چې په مونږ حمله کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21670, 'Habakkuk 3:17', 'Habakkuk', 3, 17, '&nbsp;اګر کۀ د اينځرو ونه غوټۍ نۀ کوى او د انګورو په بوټو کښې انګور نشته، اګر کۀ د زيتُونو فصل ناکام شى او پټى غله نۀ پېدا کوى، اګر کۀ په شپول کښې ګډې نشته او څاروى په پنډال کښې نشته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21671, 'Habakkuk 3:18', 'Habakkuk', 3, 18, '&nbsp;خو بيا هم به زۀ په مالِک خُدائ خوشحاله شم. زۀ به په خُدائ پاک په خپل خلاصونکى خوشحاله شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21672, 'Habakkuk 3:19', 'Habakkuk', 3, 19, '&nbsp;قادر مطلق خُدائ زما طاقت دے. هغه زما پښې لکه د هوسۍ د پښو په شان کوى، هغه ما د دې جوګه کوى چې په اوچتو ځايونو وګرځم. دا دُعا د موسيقۍ د مشر دپاره ده چې د رباب د تارونو سره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21673, 'Zephaniah 1:1', 'Zephaniah', 1, 1, '&nbsp;د مالِک خُدائ کلام په صفنياه نازل شو. صفنياه د کوشى زوئ او کوشى د جدلياه زوئ، او جدلياه د امرياه زوئ، او امرياه د حزقياه زوئ وو، دا کلام په هغه وخت نازل شو کله چې يوسياه د امون زوئ د يهوداه بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21674, 'Zephaniah 1:2', 'Zephaniah', 1, 2, '&nbsp;”زۀ به د زمکې د مخ نه هر يو څيز ختم کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21675, 'Zephaniah 1:3', 'Zephaniah', 1, 3, '&nbsp;”زۀ به بنى آدم او ځناور دواړه ختم کړم، زۀ به د هوا مارغان او د سمندر کبان ختم کړم. د بدعملو د کاڼو بُتان به تباه کړم او انسان به د زمکې د مخ نه ختم کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21676, 'Zephaniah 1:4', 'Zephaniah', 1, 4, '&nbsp;”زۀ به خپل لاس د يهوداه او د هغوئ ټولو خلاف وراوږد کړم څوک چې په يروشلم کښې اوسيږى. زۀ به د دې ځائ نه د بعل د عبادت يادونه، د بُت پرستانو نومونه او بُت پرسته اِمامان ختم کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21677, 'Zephaniah 1:5', 'Zephaniah', 1, 5, '&nbsp;هغه څوک چې په چتونو د نمر، سپوږمۍ او ستورو عبادت کوى او هغوئ ته سجدې کوى، او په يو وخت کښې مالِک خُدائ ته سجدې کوى او د هغۀ په نوم قسم خورى او هم په هغه وخت کښې د مولک بُت په نوم قسم خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21678, 'Zephaniah 1:6', 'Zephaniah', 1, 6, '&nbsp;او دا هم هغه خلق دى چا چې ما ته شا کړې ده او زما لټون نۀ کوى او نۀ زما لارښودنه غواړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21679, 'Zephaniah 1:7', 'Zephaniah', 1, 7, '&nbsp;د مالِک خُدائ په وړاندې خاموشه اوسه، ځکه چې د مالِک خُدائ د قيامت ورځ نزدې ده. مالِک خُدائ يوه قربانى تياره کړې ده، هغۀ هغه څوک مقدس کړى دى چې هغۀ راغوښتى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21680, 'Zephaniah 1:8', 'Zephaniah', 1, 8, '&nbsp;د مالِک خُدائ د قربانۍ په ورځ به زۀ شهزادګانو او د بادشاه زامنو له سزا ورکړم او هر هغه چا له چې د غېر قومونو جامې اچوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21681, 'Zephaniah 1:9', 'Zephaniah', 1, 9, '&nbsp;په هغه ورځ به زۀ هغوئ ټولو له سزا ورکړم څوک چې د بُت د عزت دپاره په درشل وردانګى، د خپلو مالِکانو کورونه د ظلم او ټګۍ نه ډکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21682, 'Zephaniah 1:10', 'Zephaniah', 1, 10, '&nbsp;په هغه ورځ،“ مالِک خُدائ فرمائى، ”يوه چغه به د کب دروازې نه اوچته شى، د ښار د نوې حصې نه به ماتم، او د غونډو نه به د ماتېدو آوازونه راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21683, 'Zephaniah 1:11', 'Zephaniah', 1, 11, '&nbsp;د غم فرياد وکړئ، تاسو ټول چې په نوې ښار کښې اوسېږئ، ستاسو ټول سوداګر به جارُو شى، هغه ټول چې د سپينو زرو روزګار کوى هغه به تباه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21684, 'Zephaniah 1:12', 'Zephaniah', 1, 12, '&nbsp;زۀ به ډيوه په لاس ګوټ په ګوټ په يروشلم کښې وګرځم. زۀ به هغه خلقو له سزا ورکړم چې په خپل ځان مطمئن دى، هغه څوک چې دا سوچ کوى چې مالِک خُدائ به مونږ سره نۀ ښۀ کوى او نۀ بد.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21685, 'Zephaniah 1:13', 'Zephaniah', 1, 13, '&nbsp;د هغوئ مال دولت به لوټ شى او د هغوئ کورونه به وران شى. هغوئ به کورونه جوړوى خو په کښې به نۀ اوسيږى، هغوئ به د انګورو باغونه وکَرى خو مے به ترې ونۀ څښى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21686, 'Zephaniah 1:14', 'Zephaniah', 1, 14, '&nbsp;د مالِک خُدائ د قيامت لويه ورځ رانزدې ده، ډېره نزدې ده او زر راتلونکى ده. غوږ شئ، د مالِک خُدائ د ورځ ژړا به سخته وى، په هغه ورځ به ښۀ تکړه فوجيان هم چغې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21687, 'Zephaniah 1:15', 'Zephaniah', 1, 15, '&nbsp;هغه به د غضب ورځ وى، د غم او مصيبت ورځ به وى، د تباهۍ او بربادۍ ورځ به وى، د تورې تيارې او خړې ورځ به وى او د تکې تورې وريځې ورځ به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21688, 'Zephaniah 1:16', 'Zephaniah', 1, 16, '&nbsp;د بيګل غږولو او د جنګى نعرو ورځ چې د مضبوطو ښارونو خلاف او د لوړو برجونو خلاف به وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21689, 'Zephaniah 1:17', 'Zephaniah', 1, 17, '&nbsp;زۀ به په خلقو داسې مصيبتونه راولم چې هغوئ به د ړندو په شان ګرځى. ځکه چې هغوئ زما خلاف ګناه کړې ده. د هغوئ وينه به د خاورو په شان تويه شى او د هغوئ لاشونه به سخا شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21690, 'Zephaniah 1:18', 'Zephaniah', 1, 18, '&nbsp;د مالِک خُدائ د غضب په ورځ به نۀ د هغوئ سپين زر او نۀ به د هغوئ سرۀ زر هغوئ ته خلاصون ورکولے شى. د هغۀ د غېرت په اور به ټوله دُنيا وسوزيږى ځکه چې هغه به ناګهانه د هغوئ ټولو خاتمه راولى څوک چې د زمکې په مخ باندې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21691, 'Zephaniah 2:1', 'Zephaniah', 2, 1, '&nbsp;اے بې‌شرمه قومه، يو ځائ راغونډ شئ، يو ځائ شئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21692, 'Zephaniah 2:2', 'Zephaniah', 2, 2, '&nbsp;د دې نه مخکښې چې مقرر وخت راشى او هغه ورځ مو لکه د بوسو په شان ورک کړى، د دې نه مخکښې چې د مالِک خُدائ سخت قهر په تاسو نازل شى، د دې نه مخکښې چې د مالِک خُدائ د غضب ورځ په تاسو راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21693, 'Zephaniah 2:3', 'Zephaniah', 2, 3, '&nbsp;مالِک خُدائ ولټوئ، اے د زمکې ټولو عاجزانو خلقو، تاسو چې څوک د هغۀ په احکامو عمل کوئ، صداقت ولټوئ، عاجزى ولټوئ. شايد چې تاسو د مالِک خُدائ د قهر په ورځ پټ کړے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21694, 'Zephaniah 2:4', 'Zephaniah', 2, 4, '&nbsp;غزه به پرېښودلے شى او اسقلون به شاړ او ويجاړ پاتې شى. په نيمه ورځ کښې به اشدود خالى شى او عقرون به د بېخ نه وويستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21695, 'Zephaniah 2:5', 'Zephaniah', 2, 5, '&nbsp;په تاسو دې افسوس وى څوک چې د سمندر په غاړ اوسېږئ، اے د چريتيانو خلقو، د مالِک خُدائ کلام ستاسو خلاف دے، اے کنعانه، د فلستيانو زمکې. زۀ به تا تباه کړم، او هيڅوک به باقى پاتې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21696, 'Zephaniah 2:6', 'Zephaniah', 2, 6, '&nbsp;د سمندر غاړه به د شپونکو د څرن ځائ او د ګډو شپول وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21697, 'Zephaniah 2:7', 'Zephaniah', 2, 7, '&nbsp;دا به د يهوداه د پاتې شوى قوم په قبضه کښې وى، هلته به هغوئ ته د څرن ځائ مِلاو شى. په ماښام کښې به هغوئ د اسقلون په کورونو کښې څملى. مالِک خُدائ د هغوئ خُدائ پاک به د هغوئ غمخور وى، هغه به هغوئ بيا د غلامۍ نه واپس راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21698, 'Zephaniah 2:8', 'Zephaniah', 2, 8, '&nbsp;”ما د موآب بې‌عزتى او د عمونيانو پيغورونه واورېدل، چا چې زما د خلقو بې‌عزتۍ وکړې او د هغوئ د مُلک خلاف يې دهمکيانې ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21699, 'Zephaniah 2:9', 'Zephaniah', 2, 9, '&nbsp;نو په دې وجه، زۀ ربُ الافواج د بنى اِسرائيلو خُدائ پاک، زۀ په خپل ذات قسم خورم، يقيناً موآب به لکه د سدوم په شان، او عمونيان به لکه د عموره په شان شى. دا ځائ به د دربو او د مالګې په کندو بدل شى، او د همېشه دپاره به شاړ ويجاړ شى. زما په خلقو کښې ژوندى پاتې به هغوئ لوټ کړى، زما د قوم ژوندى پاتې به د هغوئ مُلک قبضه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21700, 'Zephaniah 2:10', 'Zephaniah', 2, 10, '&nbsp;دا هغه څۀ دى چې دوئ ته به د خپل غرور په بدله کښې او د مالِک خُدائ ربُ الافواج د قوم د بې‌عزتۍ او خندا په وجه مِلاو شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');